-- Read-only, after the first poll. Generated by Build-Sql.py.
SELECT 'feed|' || p.id || '|' || p.name || '|' || f.enabled || '|' || f.consecutive_failures || '|' || coalesce(to_char(f.last_success_at, 'HH24:MI'), 'never')
       || '|' || coalesce(left(f.last_error, 60), '-')
       || '|' || (SELECT count(*) FROM articles a WHERE a.publisher_id = p.id) || ' art'
       || '|' || (SELECT count(*) FROM articles a WHERE a.publisher_id = p.id AND a.published_at IS NULL) || ' undated'
  FROM publishers p JOIN feeds f ON f.publisher_id = p.id
 WHERE p.id IN (2070,2072,2076)
    OR p.id IN (SELECT publisher_id FROM publisher_submissions s WHERE s.verification_detail LIKE '%' || '[added by Claude 2026-10-18, Build #93 Pacific feeds]') ORDER BY p.id;
SELECT 'ok|' || count(*) FILTER (WHERE f.last_success_at > now() - interval '30 minutes') || ' of 9'
  FROM feeds f WHERE f.publisher_id IN (2070,2072,2076)
    OR f.publisher_id IN (SELECT publisher_id FROM publisher_submissions s WHERE s.verification_detail LIKE '%' || '[added by Claude 2026-10-18, Build #93 Pacific feeds]');
SELECT 'placeholder|' || count(*) FROM articles WHERE id = ANY(ARRAY[659188,659199,660947,661167,661176,663833,663646]);
SELECT 'sample|' || p.name || '|' || to_char(a.published_at, 'YYYY-MM-DD') || '|' || left(a.headline, 70)
  FROM articles a JOIN publishers p ON p.id = a.publisher_id
 WHERE a.id IN (SELECT max(a2.id) FROM articles a2 WHERE a2.publisher_id IN (2070,2072,2076)
                   OR a2.publisher_id IN (SELECT publisher_id FROM publisher_submissions s WHERE s.verification_detail LIKE '%' || '[added by Claude 2026-10-18, Build #93 Pacific feeds]')
                GROUP BY a2.publisher_id);
